<style scoped>
.cn {
    position: absolute;
    inset: 0;
    overflow: hidden;
    pointer-events: none;
}

.cn__svg {
    position: absolute;
    inset: -6% -4%;
    width: 108%;
    height: 112%;
}

.cn__layer { will-change: transform; }

/* Planche d'herbier : les feuilles ne sont plus des masses mais des
   contours fuchsia posés sur un lavis rose très pâle. */
.cn__blade,
.cn__leaf {
    fill: var(--terre-100);
    fill-opacity: .3;
    stroke: var(--terre-300);
    stroke-width: 1;
    stroke-opacity: .32;
    stroke-linejoin: round;
}

.cn__leaf { fill-opacity: .24; }

.cn__rib {
    fill: none;
    stroke: var(--terre-400);
    stroke-width: 1;
    stroke-opacity: .26;
    stroke-linecap: round;
}

.cn__rib--fan { stroke-opacity: .42; }

.cn__fan .cn__leaf { fill-opacity: .38; }

/* La branche : un trait d'encre franc, l'unique ligne dense du décor */
.cn__branch {
    fill: none;
    stroke: var(--ink);
    stroke-width: 4.5;
    stroke-linecap: round;
    opacity: .5;
}

.cn__spore {
    fill: var(--terre-500);
    opacity: 0;
}

@media (max-width: 760px) {
    /* Sur mobile la canopée mange le titre : on la recule. */
    .cn__blade, .cn__leaf { fill-opacity: .22; stroke-opacity: .25; }
